"""CPU audit of public, actual-native-host PID supplement for the frozen RC2 runner."""
import argparse,hashlib,io,json,zipfile
from pathlib import Path
import numpy as np
from kernel_agent.protocol import decode_frame
from kernel_agent.bounded_io import confirmed_removed
ROOT=Path(__file__).resolve().parents[2]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def audit(qualified=False):
 version='0.1.3' if qualified else '0.1.3rc2';folder=ROOT/'evidence'/('20261124-3060-ga-pid-supplement' if qualified else '20261124-3060-pid-supplement');archive=folder/'segmented-archive';raw=archive/'remote';work=raw/'pid-supplement';manifest=json.loads((archive/'execution.json').read_text())['manifest'];collection=json.loads((archive/'collection.json').read_text());assert sha(archive/'raw.zip')==collection['archive_sha256'];assert all(sha(raw/n)==m['sha256'] and (raw/n).stat().st_size==m['bytes'] for n,m in manifest.items())
 result=json.loads((work/'result.json').read_text());native=json.loads((work/'native-host.json').read_text());probe=json.loads((work/'probe-result.json').read_text());parent=json.loads((work/'parent-command.json').read_text());wheel=ROOT/'artifacts/wheels'/('nvidia_kernel_agent-'+version+'-py3-none-any.whl');assert result['status']=='ACTUAL_HOST_PID_BOUNDARY_PASS' and sha(wheel)==result['wheel_sha256'];assert native['live_before'] and native['live_after'] and native['pid_namespace'].startswith('pid:[');assert native['pid']==probe['host_pid_argument']==int(parent[parent.index('--host-pid')+1]) and native['pid']!=probe['controller_container_pid'];assert sha(work/'host.py')==sha(ROOT/'experiments/full_delivery/cdi_pid_supplement_host.py')
 with zipfile.ZipFile(wheel) as z:
  for n in z.namelist():
   if n.startswith('kernel_agent/') and not n.endswith('/'):assert hashlib.sha256(z.read(n)).hexdigest()==sha(raw/'prefix'/n)
 job=work/'probe';r=json.loads((job/'record.json').read_text());request=json.loads((job/'inputs/request.json').read_text());assert request['host_pid']==native['pid'];assert r['status']=='OUTPUT_VALID' and r['exit']==0 and r['reason'] is None and r['protected_files_unchanged'] and r['cleanup']['removed'] and confirmed_removed(r['cleanup']['inspect_after_cleanup']);assert all(sha(job/n)==h for n,h in r['protected_sha256'].items());cmd=r['command'];assert all(x!='--pid' and not x.startswith('--pid=') for x in cmd);assert cmd[cmd.index('--user')+1]=='65534:65534' and cmd.count('--mount')==2 and all('readonly' in cmd[i+1] for i,c in enumerate(cmd) if c=='--mount') and result['image_id'] in cmd
 for flag in ['--network=none','--read-only','--cap-drop=ALL','--security-opt=no-new-privileges','--pids-limit=32','--memory=2g','--runtime=runc']:assert cmd.count(flag)==1
 x=np.load(work/'a.npy',allow_pickle=False);y=np.load(work/'b.npy',allow_pickle=False);ref=x.astype(np.float64)@y.astype(np.float64);assert np.array_equal(ref,np.load(work/'reference.npy',allow_pickle=False));assert np.array_equal(x,np.load(job/'inputs/a.npy',allow_pickle=False)) and np.array_equal(y,np.load(job/'inputs/b.npy',allow_pickle=False));m,p=decode_frame(job/'capture/stdout.bin',17*19*4+16384);assert m==r['metadata']==probe['metadata'] and p==(job/'result.npy').read_bytes();a=np.load(io.BytesIO(p),allow_pickle=False);assert a.dtype==np.float32 and a.shape==ref.shape and np.isfinite(a).all() and np.all(np.abs(a-ref)<=3e-5+1e-4*np.abs(ref));assert m['uid']==65534 and m['interfaces']==['lo'] and all(m[k] is True for k in ['capabilities_zero','no_new_privs','artifact_write_denied','inputs_write_denied','external_connect_denied']) and all(m[k] is False for k in ['docker_socket_visible','control_canary_in_env','host_private_visible','host_pid_visible']);assert m['pids_max']=='32' and m['memory_max']==str(2*1024**3)
 v={'status':'AUDIT_PASS_ACTUAL_HOST_PID_SUPPLEMENT','raw_files_verified':len(manifest),'archive_sha256':collection['archive_sha256'],'wheel_sha256':sha(wheel),'image_id':result['image_id'],'actual_native_host_pid_verified':True,'private_pid_namespace_command_verified':True,'gpu_outputs':1,'independent_dataset_rerun':False,'new_model_calls':0};(folder/'verification.json').write_text(json.dumps(v,indent=2));return v
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--qualified',action='store_true');a=p.parse_args();print(json.dumps(audit(a.qualified)))
